<template><div class="task-page"><el-card class="filter-card"><el-form inline><el-form-item label="关键词"><el-input v-model="filters.keyword" clearable/></el-form-item><el-form-item label="主题"><el-input v-model="filters.topic" clearable/></el-form-item><el-form-item label="状态"><el-select v-model="filters.status" clearable style="width:130px"><el-option v-for="o in statuses" :key="o.value" :label="o.label" :value="o.value"/></el-select></el-form-item><el-button type="primary" @click="load">查询</el-button></el-form></el-card>
<el-card><template #header><div class="task-card-header"><span>学习计划</span><el-button type="primary" @click="open()">新建计划</el-button></div></template><el-table :data="plans" v-loading="loading"><el-table-column prop="title" label="计划" min-width="180"/><el-table-column prop="topic" label="主题" width="130"/><el-table-column prop="stage" label="当前阶段" width="140"/><el-table-column label="进度" width="180"><template #default="{row}"><el-progress :percentage="row.progress"/></template></el-table-column><el-table-column prop="targetDate" label="目标日期" width="120"/><el-table-column label="状态" width="100"><template #default="{row}">{{statusLabel(row.status)}}</template></el-table-column><el-table-column label="操作" width="150"><template #default="{row}"><el-button link type="primary" @click="open(row)">编辑</el-button><el-button link type="danger" @click="remove(row)">归档</el-button></template></el-table-column></el-table></el-card>
<el-dialog v-model="visible" :title="editing?'编辑计划':'新建计划'" width="680px"><el-form ref="formRef" :model="form" :rules="rules" label-width="90px"><el-form-item label="计划标题" prop="title"><el-input v-model="form.title"/></el-form-item><el-row :gutter="16"><el-col :span="12"><el-form-item label="学习主题" prop="topic"><el-input v-model="form.topic"/></el-form-item></el-col><el-col :span="12"><el-form-item label="当前阶段"><el-input v-model="form.stage"/></el-form-item></el-col></el-row><el-form-item label="学习目标"><el-input v-model="form.target" type="textarea" :rows="3"/></el-form-item><el-row :gutter="16"><el-col :span="12"><el-form-item label="开始日期"><el-date-picker v-model="form.startDate" value-format="YYYY-MM-DD" style="width:100%"/></el-form-item></el-col><el-col :span="12"><el-form-item label="目标日期"><el-date-picker v-model="form.targetDate" value-format="YYYY-MM-DD" style="width:100%"/></el-form-item></el-col></el-row><el-form-item label="学习进度" prop="progress"><el-slider v-model="form.progress" show-input/></el-form-item><el-form-item label="状态"><el-select v-model="form.status"><el-option v-for="o in statuses" :key="o.value" :label="o.label" :value="o.value"/></el-select></el-form-item><el-form-item label="资料链接"><el-input v-model="form.resourceLinks" type="textarea" :rows="2" placeholder="每行一个链接"/></el-form-item><el-form-item label="复习时间"><el-date-picker v-model="form.reviewTime" type="datetime" value-format="YYYY-MM-DDTHH:mm:ss"/></el-form-item></el-form><template #footer><el-button @click="visible=false">取消</el-button><el-button type="primary" @click="save">保存</el-button></template></el-dialog></div></template>
<script setup lang="ts">import type{FormInstance,FormRules}from'element-plus';import{ElMessage,ElMessageBox}from'element-plus';import{onMounted,reactive,ref}from'vue';import{archivePlan,createPlan,listPlans,updatePlan,type LearningPlan,type PlanPayload}from'@/api/learning';const statuses=[{label:'未开始',value:'NOT_STARTED'},{label:'进行中',value:'IN_PROGRESS'},{label:'已完成',value:'COMPLETED'}];const plans=ref<LearningPlan[]>([]),loading=ref(false),visible=ref(false),editing=ref<number>(),formRef=ref<FormInstance>();const filters=reactive({keyword:'',topic:'',status:''});const blank=():PlanPayload=>({title:'',topic:'',target:'',stage:'',startDate:null,targetDate:null,progress:0,status:'NOT_STARTED',resourceLinks:'',reviewTime:null});const form=reactive(blank());const rules:FormRules={title:[{required:true,message:'请输入计划标题'}],topic:[{required:true,message:'请输入学习主题'}],progress:[{type:'number',min:0,max:100,message:'进度范围为 0 到 100'}]};function statusLabel(v:string){return statuses.find(x=>x.value===v)?.label||v;}async function load(){loading.value=true;try{plans.value=(await listPlans(filters)).data;}finally{loading.value=false;}}function open(row?:LearningPlan){editing.value=row?.id;Object.assign(form,blank(),row||{});visible.value=true;}async function save(){if(!(await formRef.value?.validate()))return;editing.value?await updatePlan(editing.value,form):await createPlan(form);ElMessage.success('保存成功');visible.value=false;await load();}async function remove(row:LearningPlan){await ElMessageBox.confirm(`确认归档“${row.title}”？`);await archivePlan(row.id);await load();}onMounted(load);</script>